import { useCallback, useMemo, useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
};

const DAY_MS = 24 * 60 * 60 * 1000;

function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function shiftDays(days: number): Date {
  return startOfDay(new Date(Date.now() - days * DAY_MS));
}

function isSameDay(a: Date | null, b: Date | null): boolean {
  if (!a || !b) return false;
  return startOfDay(a).getTime() === startOfDay(b).getTime();
}

export default function ReportDatePicker({ value, defaultValue = null, onChange }: ReportDatePickerProps) {
  const [internalDate, setInternalDate] = useState<Date | null>(defaultValue);
  const selected = value !== undefined ? value : internalDate;

  const presets = useMemo(
    () => [
      { id: 'today', label: 'Сегодня', days: 0 },
      { id: 'yesterday', label: 'Вчера', days: 1 },
      { id: 'week-ago', label: 'Неделя назад', days: 7 },
    ],
    [],
  );

  const applyDate = useCallback(
    (next: Date | null) => {
      if (value === undefined) setInternalDate(next);
      onChange?.(next);
    },
    [onChange, value],
  );

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '12px',
        padding: '16px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {presets.map((preset) => (
          <JxChip
            key={preset.id}
            active={isSameDay(selected, shiftDays(preset.days))}
            onClick={() => applyDate(shiftDays(preset.days))}
          >
            {preset.label}
          </JxChip>
        ))}
      </div>

      <JxCalendar locale="ru-RU" value={selected} onValueChange={applyDate} />
    </div>
  );
}

